-- PostgreSQL port of ../db.sql. The MariaDB "zimbra" database becomes the "zimbra" schema; run it
-- in the mailbox database as the role that owns it. Mapping:
--   INTEGER UNSIGNED                -> INTEGER, or BIGINT for UNIX timestamps (2038)
--   TINYINT                         -> SMALLINT
--   TEXT/MEDIUMTEXT                 -> TEXT
--   DATETIME                        -> TIMESTAMP
--   AUTO_INCREMENT                  -> GENERATED BY DEFAULT AS IDENTITY
--   VARCHAR BINARY                  -> VARCHAR COLLATE "C"
--   prefix indexes, ENGINE          -> dropped

CREATE SCHEMA IF NOT EXISTS zimbra;

CREATE TABLE zimbra.volume (
   id                     SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
   type                   SMALLINT NOT NULL,   -- 1 = primary msg, 2 = secondary msg, 10 = index
   name                   VARCHAR(255) NOT NULL,
   path                   TEXT NOT NULL,
   file_bits              SMALLINT NOT NULL,
   file_group_bits        SMALLINT NOT NULL,
   mailbox_bits           SMALLINT NOT NULL,
   mailbox_group_bits     SMALLINT NOT NULL,
   compress_blobs         BOOLEAN NOT NULL,
   compression_threshold  BIGINT NOT NULL,
   metadata               TEXT,

   CONSTRAINT i_name UNIQUE (name),
   CONSTRAINT i_path UNIQUE (path)
);

CREATE TABLE zimbra.current_volumes (
   message_volume_id            SMALLINT NOT NULL REFERENCES zimbra.volume(id),
   secondary_message_volume_id  SMALLINT REFERENCES zimbra.volume(id),
   index_volume_id              SMALLINT NOT NULL REFERENCES zimbra.volume(id),
   next_mailbox_id              INTEGER NOT NULL
);

INSERT INTO zimbra.volume (id, type, name, path, file_bits, file_group_bits,
    mailbox_bits, mailbox_group_bits, compress_blobs, compression_threshold)
  VALUES (1, 1, 'message1', '/opt/zextras/store', 12, 8, 12, 8, FALSE, 4096);
INSERT INTO zimbra.volume (id, type, name, path, file_bits, file_group_bits,
    mailbox_bits, mailbox_group_bits, compress_blobs, compression_threshold)
  VALUES (2, 10, 'index1', '/opt/zextras/index', 12, 8, 12, 8, FALSE, 4096);
SELECT setval(pg_get_serial_sequence('zimbra.volume', 'id'), 2);

INSERT INTO zimbra.current_volumes (message_volume_id, index_volume_id, next_mailbox_id) VALUES (1, 2, 1);

CREATE TABLE zimbra.volume_blobs (
  id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  volume_id   SMALLINT NOT NULL,
  mailbox_id  INTEGER NOT NULL,
  item_id     INTEGER NOT NULL,
  revision    INTEGER NOT NULL,
  blob_digest VARCHAR(44),
  processed   BOOLEAN DEFAULT FALSE,

  CONSTRAINT uc_blobinfo UNIQUE (volume_id, mailbox_id, item_id, revision)
);
CREATE INDEX i_blob_digest ON zimbra.volume_blobs (blob_digest);

CREATE TABLE zimbra.mailbox (
   id                   INTEGER NOT NULL PRIMARY KEY,
   group_id             INTEGER NOT NULL,
   account_id           VARCHAR(127) NOT NULL,
   index_volume_id      SMALLINT NOT NULL REFERENCES zimbra.volume(id),
   item_id_checkpoint   INTEGER NOT NULL DEFAULT 0,
   contact_count        INTEGER DEFAULT 0,
   size_checkpoint      BIGINT NOT NULL DEFAULT 0,
   change_checkpoint    INTEGER NOT NULL DEFAULT 0,
   tracking_sync        INTEGER NOT NULL DEFAULT 0,
   tracking_imap        BOOLEAN NOT NULL DEFAULT FALSE,
   last_backup_at       BIGINT,
   comment              VARCHAR(255),
   last_soap_access     BIGINT NOT NULL DEFAULT 0,
   new_messages         INTEGER NOT NULL DEFAULT 0,
   idx_deferred_count   INTEGER NOT NULL DEFAULT 0, -- deprecated
   highest_indexed      VARCHAR(21), -- deprecated
   version              VARCHAR(16),
   last_purge_at        BIGINT NOT NULL DEFAULT 0,
   itemcache_checkpoint INTEGER NOT NULL DEFAULT 0,

   CONSTRAINT i_account_id UNIQUE (account_id)
);
CREATE INDEX i_mailbox_index_volume_id ON zimbra.mailbox (index_volume_id);
CREATE INDEX i_last_backup_at ON zimbra.mailbox (last_backup_at, id);

CREATE TABLE zimbra.deleted_account (
   email       VARCHAR(255) NOT NULL PRIMARY KEY,
   account_id  VARCHAR(127) NOT NULL,
   mailbox_id  INTEGER NOT NULL,
   deleted_at  BIGINT NOT NULL
);

CREATE TABLE zimbra.mailbox_metadata (
   mailbox_id  INTEGER NOT NULL REFERENCES zimbra.mailbox(id) ON DELETE CASCADE,
   section     VARCHAR(64) NOT NULL,
   metadata    TEXT,

   PRIMARY KEY (mailbox_id, section)
);

CREATE TABLE zimbra.out_of_office (
   mailbox_id  INTEGER NOT NULL REFERENCES zimbra.mailbox(id) ON DELETE CASCADE,
   sent_to     VARCHAR(255) NOT NULL,
   sent_on     TIMESTAMP NOT NULL,

   PRIMARY KEY (mailbox_id, sent_to)
);
CREATE INDEX i_sent_on ON zimbra.out_of_office (sent_on);

CREATE TABLE zimbra.config (
   name         VARCHAR(255) NOT NULL PRIMARY KEY,
   value        TEXT,
   description  TEXT,
   modified     TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE zimbra.table_maintenance (
   database_name       VARCHAR(64) NOT NULL,
   table_name          VARCHAR(64) NOT NULL,
   maintenance_date    TIMESTAMP NOT NULL,
   last_optimize_date  TIMESTAMP,
   num_rows            INTEGER NOT NULL,

   PRIMARY KEY (table_name, database_name)
);

CREATE TABLE zimbra.service_status (
   server   VARCHAR(255) NOT NULL,
   service  VARCHAR(255) NOT NULL,
   time     TIMESTAMP,
   status   BOOLEAN,

   CONSTRAINT i_server_service UNIQUE (server, service)
);

CREATE TABLE zimbra.scheduled_task (
   class_name       VARCHAR(255) COLLATE "C" NOT NULL,
   name             VARCHAR(255) NOT NULL,
   mailbox_id       INTEGER NOT NULL REFERENCES zimbra.mailbox(id) ON DELETE CASCADE,
   exec_time        TIMESTAMP,
   interval_millis  INTEGER,
   metadata         TEXT,

   PRIMARY KEY (name, mailbox_id, class_name)
);
CREATE INDEX i_scheduled_task_mailbox_id ON zimbra.scheduled_task (mailbox_id);

CREATE TABLE zimbra.pending_acl_push (
   mailbox_id  INTEGER NOT NULL REFERENCES zimbra.mailbox(id) ON DELETE CASCADE,
   item_id     INTEGER NOT NULL,
   date        BIGINT NOT NULL,

   PRIMARY KEY (mailbox_id, item_id, date)
);
CREATE INDEX i_date ON zimbra.pending_acl_push (date);

CREATE TABLE zimbra.current_sessions (
   id         INTEGER NOT NULL,
   server_id  VARCHAR(127) NOT NULL,
   PRIMARY KEY (id, server_id)
);
